from math import sqrt

def min_time(x1, y1, x2, y2, vmax, t, winds):
    def distance(x1, y1, x2, y2):
        return sqrt((x2 - x1)**2 + (y2 - y1)**2)

    def simulate_wind(uvx, uvy, wx, wy, x, y, t):
        for _ in range(t):
            x += uvx
            y += uvy
        x += wx * t
        y += wy * t
        return x, y

    def simulate_without_wind(vx, vy, x, y, t):
        for _ in range(t):
            x += vx
            y += vy
        return x, y

    def cost(uvx, uvy, wx, wy, x1, y1, x2, y2, t):
        ex, ey = simulate_wind(uvx, uvy, wx, wy, x1, y1, t)
        return distance(ex, ey, x2, y2)

    def binary_search(x1, y1, x2, y2, vmax, t, winds):
        left, right = 0, max(distance(x1, y1, x2, y2), t)
        while right - left > 1e-9:
            mid = (left + right) / 2
            if cost(*winds[0], *winds[1], x1, y1, x2, y2, mid) <= mid * vmax:
                right = mid
            else:
                left = mid
        return left

    return binary_search(x1, y1, x2, y2, vmax, t, winds)

