import math

def min_time_to_reach(x1, y1, x2, y2, vmax, t, wind1, wind2):
    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def project_vector(v, d):
        norm = math.sqrt(v[0]**2 + v[1]**2)
        return (v[0] * d / norm, v[1] * d / norm)

    def simulate(x, y, vx, vy, wind, dt):
        return (x + vx * dt, y + vy * dt, vx, vy, wind)

    def heuristic(current, goal):
        return distance(current, goal)

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
        return total_path[::-1]

    open_set = {(x1, y1, 0, 0, wind1)}
    came_from = {}
    g_score = {(x1, y1, 0, 0, wind1): 0}
    f_score = {(x1, y1, 0, 0, wind1): heuristic((x1, y1), (x2, y2))}

    while open_set:
        current = min(open_set, key=lambda pos: f_score[pos])

        if abs(current[0] - x2) <= 1e-6 and abs(current[1] - y2) <= 1e-6:
            return f_score[current]

        open_set.remove(current)

        for wx, wy in [wind1, wind2]:
            for dx, dy in [(vx, vy) for vx in range(-vmax, vmax+1) for vy in range(-vmax, vmax+1)]:
                nx, ny, nvx, nvy = simulate(current[0], current[1], dx, dy, wx, 1)
                tentative_g_score = g_score[current] + 1

                if (nx, ny, nvx, nvy, wx) not in g_score or tentative_g_score < g_score[(nx, ny, nvx, nvy, wx)]:
                    came_from[(nx, ny, nvx, nvy, wx)] = current
                    g_score[(nx, ny, nvx, nvy, wx)] = tentative_g_score
                    f_score[(nx, ny, nvx, nvy, wx)] = tentative_g_score + heuristic((nx, ny), (x2, y2))
                    open_set.add((nx, ny, nvx, nvy, wx))

    return float('inf')

