import sys
from typing import List, Tuple

def min_time_to_rescue(x1: int, y1: int, x2: int, y2: int, vmax: int, t: int, winds: List[Tuple[int, int]]) -> float:
    def distance(p1: Tuple[int, int], p2: Tuple[int, int]) -> float:
        return ((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)**0.5

    def simulate(time_left: float, pos: Tuple[int, int], vel: Tuple[int, int], wind: Tuple[int, int]) -> bool:
        if time_left <= 0:
            return distance(pos, (x2, y2)) == 0

        nx, ny = pos[0] + time_left * (vel[0] + wind[0]), pos[1] + time_left * (vel[1] + wind[1])
        if distance((nx, ny), (x2, y2)) <= time_left * vmax:
            return True

        dt = time_left / 2.0
        if simulate(dt, pos, vel, wind):
            return True

        dv = (vmax**2 - (vel[0]**2 + vel[1]**2)) ** 0.5
        dx, dy = max(0, x2 - pos[0]), max(0, y2 - pos[1])
        dv = min(dv, dx / dt, dy / dt)

        nx, ny = pos[0] + dt * (vel[0] + wind[0] + dv * (dx / distance((pos[0], pos[1]), (x2, y2)))), pos[1] + dt * (vel[1] + wind[1] + dv * (dy / distance((pos[0], pos[1]), (x2, y2)))))
        if simulate(time_left - dt, (nx, ny), (vel[0] + dv * (dx / distance((pos[0], pos[1]), (x2, y2))), vel[1] + dv * (dy / distance((pos[0], pos[1]), (x2, y2)))), wind):
            return True

        return False

    time_left = distance((x1, y1), (x2, y2))
    if time_left <= vmax:
        return time_left

    best_time = float('inf')
    for i in range(t + 1):
        time_left = distance((x1, y1), (x2, y2))
        for j in range(i + 1):
            nx, ny = x1 + i * winds[0][0] + j * winds[1][0], y1 + i * winds[0][1] + j * winds[1][1]
            for k in range(vmax + 1):
                for l in range(k + 1):
                    if simulate(time_left - (i + j + k + l), (nx, ny), (k * (x2 - nx) / distance((nx, ny), (x2, y2)), l * (y2 - ny) / distance((nx, ny), (x2, y2))), (winds[t][0], winds[t][1])):
                        best_time = min(best_time, (i + j + k + l) + time_left / (vmax * max(k, l)))

    return best_time

